sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    // A UI Policy já tornou o campo somente leitura.
    // O Client Script apenas exibe a mensagem.

    // Pega a data de hoje sem a hora
    var today = new Date();
    today.setHours(0, 0, 0, 0);

    // Pega a data selecionada
    var selectedDate = new Date(newValue);
    selectedDate.setHours(0, 0, 0, 0);

    if (selectedDate > today) {
        g_form.addErrorMessage('A data do reembolso deve ser anterior ou igual ao dia de hoje.');
    } else {
        // Remove a mensagem se a data for válida
        g_form.clearMessages();
    }
}
